<?php require dirname(__DIR__).'/config.php';$pdo=db();if(!empty($_SESSION['admin_id'])){header('Location: index.php');exit;}verify_csrf();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("SELECT * FROM admins WHERE username=? LIMIT 1");$s->execute([trim($_POST['username']??'')]);$a=$s->fetch();if($a&&password_verify($_POST['password']??'',$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['username'];header('Location: index.php');exit;}$error='Incorrect username or password.';}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login — Aastha</title><link rel="stylesheet" href="../assets/css/admin.css"></head><body class="login-body"><form class="login-card" method="post"><div class="login-logo">A</div><h1>Aastha Admin</h1><p>Sign in to manage your store</p><?php if($error): ?><div class="notice error"><?=e($error)?></div><?php endif; ?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Username<input name="username" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button class="btn primary full">Sign in</button><small>First setup: create your admin with <code>setup-admin.php</code>, then delete that file.</small></form></body></html>